import XCTest

@MainActor final class FirstRunJourneyTests:XCTestCase {
    private func launch(language:String="en",theme:String="light")->XCUIApplication {
        continueAfterFailure=false;let app=XCUIApplication();app.launchEnvironment["PIYALI_OFFLINE_TESTS"]="1";app.launchEnvironment["PIYALI_TEST_IDENTITY_SCOPE"]=UUID().uuidString;app.launchEnvironment["PIYALI_ENTRY_INITIAL_LANGUAGE"]=language;app.launchEnvironment["PIYALI_ENTRY_INITIAL_THEME"]=theme;app.launchArguments=["-AppleLanguages","(en)","-AppleLocale","en_US"];app.launch()
        let name=app.textFields["entryName"];XCTAssertTrue(name.waitForExistence(timeout:15));name.tap();name.typeText("Setup Learner");app.buttons["entryKeyboardDone"].tap();app.buttons["createAccount"].tap();XCTAssertTrue(app.buttons["startLearning"].waitForExistence(timeout:20));app.buttons["startLearning"].tap();XCTAssertTrue(app.staticTexts["todayFocusTitle"].waitForExistence(timeout:15));return app
    }
    private func reveal(_ element:XCUIElement,_ app:XCUIApplication,modal:Bool=false) {for _ in 0..<10 where !element.isHittable {app.coordinate(withNormalizedOffset:CGVector(dx:modal ? 0.87 : 0.97,dy:0.78)).press(forDuration:0.1,thenDragTo:app.coordinate(withNormalizedOffset:CGVector(dx:modal ? 0.87 : 0.97,dy:0.30)),withVelocity:.slow,thenHoldForDuration:0.1)};XCTAssertTrue(element.isHittable)}
    private func shot(_ name:String,_ app:XCUIApplication) {let capture=XCTAttachment(screenshot:app.screenshot());capture.name=name;capture.lifetime = .keepAlways;add(capture)}
    private func continueCompanion(_ app:XCUIApplication) {let button=app.buttons["companionContinue"];reveal(button,app);button.tap()}
    func testGuidanceWebInstructionsPlacementDismissalAndNewLanguageAfterRelaunch() {
        let app=launch();continueCompanion(app);XCTAssertTrue(app.staticTexts["gettingStartedTitle"].waitForExistence(timeout:5));XCTAssertTrue(app.buttons["gettingStartedCopy"].isHittable);XCTAssertFalse(app.buttons["placementNew"].exists);shot("Native first-run installed and key guidance light",app)
        app.buttons["Install the web app"].tap();XCTAssertTrue(app.staticTexts["1. Open the browser menu."].waitForExistence(timeout:5));let webLink=app.descendants(matching:.any).matching(identifier:"gettingStartedWebLink").firstMatch;if !webLink.exists {print(app.debugDescription)};XCTAssertTrue(webLink.exists);shot("Native first-run original web instructions",app)
        let gotIt=app.buttons["gettingStartedGotIt"];reveal(gotIt,app,modal:true);gotIt.tap();XCTAssertTrue(app.buttons["placementNew"].waitForExistence(timeout:5));XCTAssertFalse(app.staticTexts["gettingStartedTitle"].exists);XCTAssertEqual(app.buttons["placementNew"].frame.minY-app.buttons["placementClose"].frame.midY,142.39,accuracy:2);shot("Native chained starting-level choice light",app)
        app.buttons["placementClose"].tap();XCTAssertFalse(app.buttons["placementNew"].exists);app.terminate();app.launch();XCTAssertTrue(app.staticTexts["todayFocusTitle"].waitForExistence(timeout:15));XCTAssertFalse(app.staticTexts["gettingStartedTitle"].exists)
        app.buttons["productMenu"].tap();app.buttons["productPanel-settings"].tap();let picker=app.descendants(matching:.any).matching(identifier:"practiceLanguagePicker").firstMatch;XCTAssertTrue(picker.waitForExistence(timeout:5));picker.tap();let french=app.buttons["French"].firstMatch;XCTAssertTrue(french.waitForExistence(timeout:5));french.tap();app.buttons["productPanelClose"].tap()
        continueCompanion(app);XCTAssertTrue(app.buttons["placementFindLevel"].waitForExistence(timeout:5));XCTAssertFalse(app.staticTexts["gettingStartedTitle"].exists)
        app.buttons["placementFindLevel"].tap();let common=app.buttons["placementOption-common_words"];XCTAssertTrue(common.waitForExistence(timeout:5));common.tap();let next=app.buttons["placementNext"];reveal(next,app,modal:true);next.tap();reveal(next,app,modal:true);next.tap();let start=app.buttons["placementStart"];reveal(start,app,modal:true);shot("Native chained placement result light",app);start.tap();XCTAssertFalse(app.buttons["placementStart"].exists);app.terminate();app.launch();XCTAssertTrue(app.staticTexts["todayFocusTitle"].waitForExistence(timeout:15));XCTAssertFalse(app.staticTexts["gettingStartedTitle"].exists)
    }
    func testArabicDarkOverlayAcknowledgmentAndSettingsReopenGuidance() {
        let app=launch(language:"ar",theme:"dark");continueCompanion(app);XCTAssertTrue(app.staticTexts["gettingStartedTitle"].waitForExistence(timeout:5));shot("Native first-run Arabic dark guidance",app);XCUIDevice.shared.press(.home);app.activate();XCTAssertTrue(app.staticTexts["gettingStartedTitle"].waitForExistence(timeout:10))
        app.coordinate(withNormalizedOffset:CGVector(dx:0.01,dy:0.5)).tap();XCTAssertTrue(app.buttons["placementNew"].waitForExistence(timeout:5));shot("Native chained Arabic dark placement",app)
        app.buttons["placementFindLevel"].tap();app.buttons["placementOption-common_words"].tap();let next=app.buttons["placementNext"];reveal(next,app,modal:true);next.tap();reveal(next,app,modal:true);next.tap();let start=app.buttons["placementStart"];reveal(start,app,modal:true);shot("Native chained Arabic dark placement result",app);app.buttons["placementClose"].tap()
        app.buttons["productMenu"].tap();app.buttons["productPanel-settings"].tap();let setup=app.buttons["accountGettingStarted"];reveal(setup,app);setup.tap();XCTAssertTrue(app.staticTexts["gettingStartedTitle"].waitForExistence(timeout:5));let gotIt=app.buttons["gettingStartedGotIt"];reveal(gotIt,app,modal:true);gotIt.tap();XCTAssertTrue(app.buttons["productPanelClose"].waitForExistence(timeout:5));XCTAssertFalse(app.buttons["placementNew"].exists)
    }
}
